def features(p):
 g=p['input']; out=p['output']; n=len(g); m=len(g[0])
 seps=[(r,row[0]) for r,row in enumerate(g) if row[0]!=0 and len(set(row))==1]
 obs=[]; marks=[]
 for i,(r,c) in enumerate(seps):
  if c==9:continue
  end=seps[i+1][0] if i+1<len(seps) else n
  cells=[(rr,cc) for rr in range(r+1,end) for cc in range(m) if g[rr][cc]==c]
  marks += [(rr,cc) for rr in range(r+1,end) for cc in range(m) if g[rr][cc]==5]
  if cells: obs.append((c, min(x[0] for x in cells)-r, max(x[0] for x in cells)-min(x[0] for x in cells)+1,min(x[1] for x in cells),max(x[1] for x in cells)))
  else:obs.append(None)
 marked=[i for i,row in enumerate(out) if 5 in row][0]
 return obs,marks,marked,[sum(x==c for x in row[:3]) for row,c in zip(out,[o[0] for o in obs if o])]
